{"type": "run_bash", "command": "cat > /app/output/compute.py << 'EOF'
import csv, json
from datetime import date, datetime
REPORT=date(2026,7,31)

def p(s):
    return datetime.strptime(s.strip(),"%Y-%m-%d").date() if s.strip() else None

# loans
loans={}
for r in csv.DictReader(open("/app/data/loans.csv")):
    loans[r["loan_id"]]=r

# writeoffs
wo=set(r["loan_id"] for r in csv.DictReader(open("/app/data/writeoffs.csv")))

# fx for report date
fx={}
for r in csv.DictReader(open("/app/finance/fx_rates.csv")):
    if r["date"]=="2026-07-31":
        fx[r["ccy"]]=float(r["eur_per_unit"])

# payments
unpaid={lid:set() for lid in loans}
for r in csv.DictReader(open("/app/data/payments.csv")):
    lid=r["loan_id"]; dd=p(r["due_date"]); pd=p(r["paid_date"])
    if lid in loans:
        unpaid[lid].add((dd,pd))

# returned
for r in csv.DictReader(open("/app/data/payments_returned.csv")):
    lid=r["loan_id"]; dd=p(r["due_date"])
    if lid in loans:
        unpaid[lid].discard((dd,pd))  # no-op placeholder

# apply returned: remove matching (due_date) as paid -> make unpaid
returned={(r["loan_id"],r["due_date"]) for r in csv.DictReader(open("/app/data/payments_returned.csv"))}

stage1=[];stage2=[];stage3=[]
total=0.0
for lid,info in loans.items():
    if lid in wo:
        continue
    # find oldest unpaid
    best=None
    for (dd,pd) in unpaid[lid]:
        if (lid,dd.isoformat()) in returned:
            paid=False
        else:
            paid = (pd is not None and pd <= REPORT)
        if not paid:
            dpd=(REPORT-dd).days
            if best is None or dpd>best[0]:
                best=(dpd,dd)
    dpd=best[0] if best else 0
    if dpd==0 or 0<=dpd<=30:
        st=1; rate=1
    elif 31<=dpd<=90:
        st=2; rate=14
    else:
        st=3; rate=50
    bal=float(info["outstanding_balance"])
    ccy=info["currency"]
    rate_fx=1.0 if ccy=="EUR" else fx[ccy]
    eur=round(bal*rate_fx,2)
    prov=round(eur*rate/100,2)
    total+=prov
    if st==1: pass
    elif st==2: stage2.append(lid)
    else: stage3.append(lid)

total=round(total,2)
print("stage1count",len(stage1)-0)
res={
 "stage2_loans":sorted(stage2),
 "stage3_loans":sorted(stage3),
 "total_provision_eur":total,
 "discrepancies":[]
}
# discrepancy: request says L-1549,L-1653,L-2784 written off; check
for x in ["L-1549","L-1653","L-2784"]:
    if x not in wo:
        res["discrepancies"].append(x)
res["discrepancies"]=sorted(set(res["discrepancies"]))
json.dump(res,open("/app/output/provisions.json","w"),indent=2)
print(json.dumps(res,indent=2))
EOF
