import pandas as pd, json

LIQ=227
runs=pd.read_csv('data/runs.csv')
boards=pd.read_csv('data/boards.csv')
tc=pd.read_csv('data/thermocouples.csv')

ref=boards[boards.role=='reference'].set_index('run_id')['tc_id']
runs2=runs.set_index('run_id')

out={'ramp_limit_c_per_s':1.5,'runs':{},'failing_runs':[]}
for rid in sorted(runs2.index):
    r=runs2.loc[rid]
    tcid=ref.get(rid)
    if tcid is None or str(tcid) not in set(tc['tc_id']):
        t=tc.iloc[0:0]
    else:
        t=tc[(tc['run_id']==rid)&(tc['tc_id']==tcid)].sort_values('t_s')
    temps=list(t['temp'].astype(float))
    ts=list(t['t_s'].astype(float))
    if len(temps)<2:
        out['runs'][rid]={'tc_id':(str(tcid) if tcid is not None else None),'max_preheat_ramp':None,'tal_s':None,'peak_c':None,'status':'non-compliant'}
        out['failing_runs'].append(rid)
        continue
    if r['temp_unit'].upper()=='F':
        temps=[(x-32)*5/9 for x in temps]
    peak=max(temps)
    tal=0.0
    for i in range(len(temps)-1):
        a,b=temps[i],temps[i+1]; ta,tb=ts[i],ts[i+1]; dt=tb-ta
        if a>=LIQ and b>=LIQ:
            tal+=dt
        elif a<LIQ<=b:
            f=(LIQ-a)/(b-a); tal+=dt*f
        elif b<LIQ<=a:
            f=(a-LIQ)/(a-b); tal+=dt*f
    idx=None
    for i,x in enumerate(temps):
        if x>160:
            idx=i; break
    ramp_max=0.0
    if idx is not None and idx>=1:
        for i in range(0,idx):
            if temps[i]>=60 and temps[i+1]>=60:
                dts=ts[i+1]-ts[i]
                ramp=(temps[i+1]-temps[i])/dts if dts>0 else 0.0
                ramp_max=max(ramp_max,ramp)
    comp=(ramp_max<=1.5) and (45<=tal<=90) and (peak>=252)
    out['runs'][rid]={'tc_id':str(tcid),'max_preheat_ramp':round(ramp_max,2),'tal_s':round(tal,2),'peak_c':round(peak,2),'status':'compliant' if comp else 'non-compliant'}
    if not comp: out['failing_runs'].append(rid)

out['failing_runs']=sorted(out['failing_runs'])
open('/app/output/reflow_report.json','w').write(json.dumps(out,indent=2))
print(json.dumps(out,indent=2))
EOF
