import csv, json
from collections import defaultdict

def to_c(t, unit):
    return t if unit=='C' else (t-32)*5/9

runs={}
with open('/app/data/runs.csv') as f:
    for r in csv.DictReader(f):
        runs[r['run_id']]=r

d=defaultdict(list)
with open('/app/data/thermocouples.csv') as f:
    for r in csv.DictReader(f):
        d[(r['run_id'],r['tc_id'])].append((float(r['t_s']),float(r['temp'])))

LIQ=217.0
RAMP_LIMIT=2.5

def compute(points, unit):
    pts=sorted((t, to_c(v,unit)) for t,v in points)
    # preheat: from start until first exceeds 140, counting only steps where both samples >=40
    max_ramp=0.0
    n=len(pts)
    # preheat region: t from 0 until first crossing of 140 (not including point after crossing? define as until board first exceeds 140)
    # We iterate over consecutive samples; ramp counted when both samples >=40, within preheat
    # find index where first exceeds 140
    idx=None
    for i,(t,v) in enumerate(pts):
        if v>140:
            idx=i; break
    # preheat includes the crossing sample
    for i in range(1, (idx+1 if idx is not None else n)):
        t0,v0=pts[i-1]; t1,v1=pts[i]
        if v0>=40 and v1>=40:
            ramp=(v1-v0)/(t1-t0)
            if ramp>max_ramp: max_ramp=ramp
    # TAL: time at or above liquidus, interpolate at crossings
    tal=0.0
    for i in range(1,n):
        t0,v0=pts[i-1]; t1,v1=pts[i]
        if v0>=LIQ and v1>=LIQ:
            tal+=t1-t0
        elif v0<LIQ and v1>=LIQ:
            # time within interval above liquidus
            if v1!=v0: tal+=(t1-t0)*(LIQ-v0)/(v1-v0)
        elif v0>=LIQ and v1<LIQ:
            if v1!=v0: tal+=(t1-t0)*(v0-LIQ)/(v0-v1)
    peak=max(v for _,v in pts)
    return max_ramp, tal, peak

result={"ramp_limit_c_per_s":RAMP_LIMIT, "runs":{}, "failing_runs":[]}
for run_id in sorted(runs):
    unit=runs[run_id]['temp_unit']
    tcs={tc for (rn,tc) in d if rn==run_id}
    if not tcs:
        result['runs'][run_id]={'tc_id':None,'max_preheat_ramp':None,'tal_s':None,'peak_c':None,'status':'non-compliant'}
        result['failing_runs'].append(run_id)
        continue
    # coldest thermocouple = lowest peak
    best_tc=None; best_peak=None
    for tc in tcs:
        pks=max(to_c(v,unit) for _,v in d[(run_id,tc)])
        if best_peak is None or pks<best_peak:
            best_peak=pks; best_tc=tc
    max_ramp, tal, peak = compute(d[(run_id,best_tc)], unit)
    status='compliant' if (max_ramp<=RAMP_LIMIT and 60<=tal<=120 and peak>=232) else 'non-compliant'
    result['runs'][run_id]={'tc_id':best_tc,'max_preheat_ramp':round(max_ramp,2),'tal_s':round(tal,2),'peak_c':round(peak,2),'status':status}
    if status=='non-compliant': result['failing_runs'].append(run_id)

print(json.dumps(result,indent=2))
with open('/app/output/reflow_report.json','w') as f:
    json.dump(result,f,indent=2)
EOF"}

