end   = "2026-09-10 22:00"

down_runs = defaultdict(list)  # machine -> list of run lengths (minutes) of DOWN
machines = set()
with open("/app/data/sensor_log.csv") as f:
    r = csv.DictReader(f)
    rows = defaultdict(dict)  # machine -> {ts: state}
    for row in r:
        m = row["machine_id"]; ts = row["timestamp"]; st = row["state"]
        rows[m][ts] = st
        machines.add(m)

for m, d in rows.items():
    d2 = {ts: st for ts, st in d.items() if start <= ts < end}
    for ts in sorted(d2):
        if d2[ts] == "DOWN":
            down_runs[m].append(ts)

# compute contiguous DOWN run lengths within the window
result = {}
for m in sorted(machines):
    d2 = {ts: st for ts, st in rows[m].items() if start <= ts < end}
    runs = []
    cur = 0
    prev_ts = None
    from datetime import datetime, timedelta
    for ts in sorted(d2):
        if d2[ts] == "DOWN":
            if cur == 0:
                cur = 1
            else:
                dt = (datetime.strptime(ts, "%Y-%m-%d %H:%M") - datetime.strptime(prev_ts, "%Y-%m-%d %H:%M")).total_seconds()/60
                if dt == 1:
                    cur += 1
                else:
                    runs.append(cur); cur = 1
            prev_ts = ts
        else:
            cur = 0
    if cur: runs.append(cur)
    # exclude micro-stops shorter than 3 minutes
    result[m] = sum(r for r in runs if r >= 3)

limit = 40
out = {
    "limit_min": limit,
    "downtime_by_machine": {m: result[m] for m in sorted(result)},
    "over_limit": [m for m in sorted(result) if result[m] > limit]
}
